    const nominated = new Set(t.allStarNominations.filter((n) => n.poolId === poolId).map((n) => n.playerId)); const own = new Set(t.players.filter((p) => p.teamId === myTeam.id).map((p) => p.id)); const problems = ballotProblems(pool, playerIds, nominated, own); if (problems.length) throw new PermissionError(problems[0]);
