    for (const pid of alternatePlayerIds) { const p = t.playerById.get(pid); if (!p) continue; for (const g of p.guardianUserIds) await actions.notify(g, `${p.firstName} is an alternate for ${pool.title}`, "If a spot opens the league will reach out. Please keep this private until the team is announced.", "team", `player-${pid}`); }
