    if (kind === "team") { const team = t.teamById.get(id); if (!team) throw new Error("Team not found"); if (!can(c.memberships, "team.manage", { leagueId: t.leagueId, teamId: id })) throw new PermissionError("Only the team's coaches or league staff can change the team logo."); await put(t.leagueId, "teams", { ...team, logoAssetId: assetId ?? undefined }); }
