    const problems = validateAnswers(f, answers); if (problems.length) throw new Error(`Please check: ${problems.map((x) => f.fields.find((fl) => fl.id === x.fieldId)?.label ?? x.fieldId).join(", ")}.`);
    const ex = t.formResponses.find((r) => r.formId === formId && r.userId === c.userId && (r.playerId ?? "") === (target?.playerId ?? "")); const doc: T.FormResponse = { id: ex?.id ?? newId("fr"), leagueId: t.leagueId, formId, userId: c.userId, playerId: target?.playerId, teamId: target?.teamId ?? (target?.playerId ? t.playerById.get(target.playerId)?.teamId : undefined), answers, submittedAt: nowIso() }; await put(t.leagueId, "formResponses", doc); await audit(t.leagueId, "form.submit", "form", formId, target?.playerId ?? ""); return doc;
