    for (const plan of t.paymentPlans.filter((p) => p.status === "active")) { const od = overdueInstallments(plan, today); const soon = dueSoon(plan, today); if (!od.length && !soon.length) continue; const p = t.playerById.get(t.registrations.find((r) => r.id === plan.registrationId)?.playerId ?? ""); const who = p ? `${p.firstName}'s registration` : "your registration"; if (od.length) await actions.notify(plan.userId, `Payment overdue for ${who}`, `${od.length === 1 ? "An installment" : `${od.length} installments`} of ${od.reduce((a, b) => a + b.amount, 0).toFixed(2)} ${od.length === 1 ? "was" : "were"} due ${od[0].dueDate}. Pay from the registration page, or message the treasurer about assistance.`, "payment", `registration-${plan.registrationId}`); else await actions.notify(plan.userId, `Installment due ${soon[0].dueDate}`, `${soon[0].amount.toFixed(2)} for ${who}.`, "payment", `registration-${plan.registrationId}`); await put(t.leagueId, "paymentPlans", { ...plan, lastReminderAt: nowIso() }); n++; }
