    for (const u of added) await actions.notify(u, `${t.userName(c.userId)} shared a game plan`, `${gp.title} · ${t.teamName(gp.teamId)}. Read-only; only the head coach can change it.`, "message", `gameplan-${gp.id}`); return next;
